-- ISSUE #33: canonical catalog rebuild from PR #34 HEAD (7938b1f)
-- Do not run automatically. Review the preflight output before execution.
BEGIN;

-- The deployed schema has UUID entity ids and no team_id column. Add the hierarchy column before preflight.
ALTER TABLE public.entities ADD COLUMN IF NOT EXISTS team_id uuid;

-- 1. Read-only compatibility preflight: fail before any destructive statement.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('entities','id'),('entities','sport'),('entities','type'),('entities','name'),('entities','slug'),('entities','active'),('entities','league_id'),('entities','team_id'),
    ('entity_aliases','entity_id'),('entity_aliases','alias'),('entity_aliases','normalized'),
    ('user_favorites','device_id'),('user_favorites','entity_id'),('news_entities','news_item_id'),('news_entities','entity_id')
  ) AS v(table_name,column_name) LOOP
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name=r.table_name AND column_name=r.column_name) THEN
      RAISE EXCEPTION 'ISSUE #33 schema mismatch: public.%.% is missing', r.table_name, r.column_name;
    END IF;
  END LOOP;
END $$;

-- 2. Snapshot the four intentionally reset tables. Other application tables are untouched.
CREATE SCHEMA IF NOT EXISTS catalog_rebuild_backup;
DROP TABLE IF EXISTS catalog_rebuild_backup.entities;
DROP TABLE IF EXISTS catalog_rebuild_backup.entity_aliases;
DROP TABLE IF EXISTS catalog_rebuild_backup.user_favorites;
DROP TABLE IF EXISTS catalog_rebuild_backup.news_entities;
CREATE TABLE catalog_rebuild_backup.entities AS TABLE public.entities;
CREATE TABLE catalog_rebuild_backup.entity_aliases AS TABLE public.entity_aliases;
CREATE TABLE catalog_rebuild_backup.user_favorites AS TABLE public.user_favorites;
CREATE TABLE catalog_rebuild_backup.news_entities AS TABLE public.news_entities;

-- 3. Intentionally reset catalog state and dependent catalog links.
DELETE FROM public.user_favorites;
DELETE FROM public.news_entities;
DELETE FROM public.entity_aliases;
UPDATE public.entities SET league_id = NULL, team_id = NULL;
DELETE FROM public.entities;

-- 4. Canonical entities, relationships, and aliases.


-- Hierarchy is represented by league_id/team_id, never by aliases.
-- Remove generated parent-team / parent-league rows so entity detection does
-- not turn a league mention into every member team/player.
DELETE FROM public.entity_aliases a
USING public.entities e
LEFT JOIN public.entities t ON t.id = e.team_id
LEFT JOIN public.entities l ON l.id = COALESCE(e.league_id, t.league_id)
WHERE a.entity_id = e.id
  AND (
    (e.type = 'team' AND l.id IS NOT NULL AND a.normalized = lower(trim(regexp_replace(translate(l.name,'ÅÄÖåäöÉéÜü','AAOaaoEeUu'),'[^[:alnum:][:space:]]',' ','g'))))
    OR
    (e.type = 'player' AND (
      (t.id IS NOT NULL AND a.normalized = lower(trim(regexp_replace(translate(t.name,'ÅÄÖåäöÉéÜü','AAOaaoEeUu'),'[^[:alnum:][:space:]]',' ','g'))))
      OR
      (l.id IS NOT NULL AND a.normalized = lower(trim(regexp_replace(translate(l.name,'ÅÄÖåäöÉéÜü','AAOaaoEeUu'),'[^[:alnum:][:space:]]',' ','g'))))
    ))
  );

-- Required catalog invariants and access paths.
CREATE UNIQUE INDEX IF NOT EXISTS entities_sport_type_slug_key ON public.entities (sport, type, slug);
CREATE INDEX IF NOT EXISTS entities_league_id_idx ON public.entities (league_id) WHERE league_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS entities_team_id_idx ON public.entities (team_id) WHERE team_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS entity_aliases_normalized_idx ON public.entity_aliases (normalized);
CREATE INDEX IF NOT EXISTS entity_aliases_entity_id_idx ON public.entity_aliases (entity_id);
CREATE UNIQUE INDEX IF NOT EXISTS entity_aliases_entity_normalized_key ON public.entity_aliases (entity_id, normalized);
ALTER TABLE public.entities DROP CONSTRAINT IF EXISTS entities_league_id_fkey;
ALTER TABLE public.entities DROP CONSTRAINT IF EXISTS entities_team_id_fkey;
ALTER TABLE public.entity_aliases DROP CONSTRAINT IF EXISTS entity_aliases_entity_id_fkey;
ALTER TABLE public.entities
  ADD CONSTRAINT entities_league_id_fkey FOREIGN KEY (league_id) REFERENCES public.entities(id),
  ADD CONSTRAINT entities_team_id_fkey FOREIGN KEY (team_id) REFERENCES public.entities(id);
ALTER TABLE public.entity_aliases
  ADD CONSTRAINT entity_aliases_entity_id_fkey FOREIGN KEY (entity_id) REFERENCES public.entities(id) ON DELETE CASCADE;

-- 5. Verification: each query must return zero rows except the count query.
SELECT sport, type, count(*) AS active_count FROM public.entities WHERE active IS TRUE GROUP BY sport, type ORDER BY sport, type;
DO $$ DECLARE bad_count integer; BEGIN SELECT count(*) INTO bad_count FROM (SELECT sport, type, count(*) FROM public.entities WHERE active IS TRUE GROUP BY sport, type EXCEPT VALUES ('football','league',12),('football','team',226),('football','player',74),('hockey','league',3),('hockey','team',60),('hockey','player',656)) q; IF bad_count <> 0 THEN RAISE EXCEPTION 'ISSUE #33 active catalog counts do not match PR #34: %', bad_count; END IF; END $$;
SELECT e.id FROM public.entities e LEFT JOIN public.entities l ON l.id=e.league_id AND l.type='league' WHERE e.type='team' GROUP BY e.id HAVING count(l.id) <> 1;
SELECT e.id FROM public.entities e LEFT JOIN public.entities t ON t.id=e.team_id AND t.type='team' WHERE e.type='player' GROUP BY e.id HAVING count(t.id) <> 1;
SELECT sport, type, slug, count(*) FROM public.entities GROUP BY sport, type, slug HAVING count(*) <> 1;
SELECT a.entity_id, a.alias FROM public.entity_aliases a LEFT JOIN public.entities e ON e.id=a.entity_id WHERE e.id IS NULL;
SELECT e.id FROM public.entities e WHERE e.type='team' AND (e.league_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.entities l WHERE l.id=e.league_id AND l.type='league' AND l.sport=e.sport));
SELECT e.id FROM public.entities e WHERE e.type='player' AND (e.team_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.entities t WHERE t.id=e.team_id AND t.type='team' AND t.sport=e.sport));

-- Expected active frontend counts from PR #34 HEAD (1,031 canonical active entities):
-- football league 12, team 226, player 74; hockey league 3, team 60, player 656.
-- Additional inactive relationship-only football rows cover PR #34 players outside focus-team leagues.
COMMIT;

